package hotel.rooms;

import java.math.BigDecimal;
import java.util.List;
import java.util.Optional;

/** The inn's rooms. They rarely change, so they live in the code. */
public final class Rooms {

    private final List<Room> allRooms = List.of(
            new Room(101, RoomType.STANDARD, 2, new BigDecimal("249.90")),
            new Room(102, RoomType.STANDARD, 2, new BigDecimal("249.90")),
            new Room(201, RoomType.DELUXE, 3, new BigDecimal("389.90")),
            new Room(202, RoomType.DELUXE, 3, new BigDecimal("389.90")),
            new Room(301, RoomType.SUITE, 4, new BigDecimal("579.90")));

    public List<Room> all() {
        return allRooms;
    }

    public Optional<Room> find(int roomNumber) {
        return allRooms.stream().filter(room -> room.number() == roomNumber).findFirst();
    }
}
package hotel.reservations;

public record Guest(String name, String email, String cpf) {
}
package hotel.reservations;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;

/** Keeps the reservations in memory: everything is lost when the service restarts. */
public final class ReservationStore {

    private final Map<Long, Reservation> reservationsById = new LinkedHashMap<>();
    private long lastId = 0;

    synchronized long nextId() {
        lastId++;
        return lastId;
    }

    synchronized void save(Reservation reservation) {
        reservationsById.put(reservation.id(), reservation);
    }

    public synchronized Optional<Reservation> find(long id) {
        return Optional.ofNullable(reservationsById.get(id));
    }

    public synchronized List<Reservation> all() {
        return new ArrayList<>(reservationsById.values());
    }
}

