        Price price(Room room, int nights, BigDecimal nightlySubtotal, String companyCode) {
            return discountedPrice(nights, nightlySubtotal, COMPANY_DISCOUNTS.get(companyCode));
        }

        @Override
        BigDecimal refund(BigDecimal amountPaid) {
            return amountPaid;
        }
    },

